package main

import (
	"fmt"
	"os"
	"strings"
	"testing"
)

// helpPageDocs names, for each printed help page, the label line that introduces its fenced block
// under CLI-3 of chapter 09 and the constant that holds it in handlers.js.
var helpPageDocs = []struct{ name, label, constName string }{
	{"top", "`kogen`, `kogen help`:", "topHelp"},
	{"intent", "`kogen intent`:", "intentHelp"},
	{"provider", "`kogen provider`:", "providerHelp"},
}

const (
	proseSectionStart = "**CLI-3 — Help pages.**"
	proseSectionEnd   = "**CLI-4"
)

// printedHelpPages returns the pages as `kogen`, `kogen intent` and `kogen provider` print them.
func printedHelpPages(t *testing.T) map[string]string {
	t.Helper()
	argv := map[string][]string{"top": nil, "intent": {"intent"}, "provider": {"provider"}}
	out := map[string]string{}
	for name, args := range argv {
		inv, page, uerr := parse(args)
		if inv != nil || uerr != nil || page == "" {
			t.Fatalf("kogen %s did not print a help page", strings.Join(args, " "))
		}
		out[name] = page
	}
	return out
}

func lineAt(lines []string, i int) string {
	if i < len(lines) {
		return fmt.Sprintf("%q", lines[i])
	}
	return "<no more lines>"
}

// comparePage compares one printed page with the text of a document, byte for byte.
func comparePage(name, source, printed, doc string) error {
	if printed == doc {
		return nil
	}
	a, b := strings.Split(printed, "\n"), strings.Split(doc, "\n")
	i := 0
	for i < len(a) && i < len(b) && a[i] == b[i] {
		i++
	}
	return fmt.Errorf("help page %s differs from %s at line %d: printed %s, %s has %s", name, source, i+1, lineAt(a, i), source, lineAt(b, i))
}

// proseBlock returns the fenced block of a page under CLI-3: the text between the opening fence
// line that follows the page's label line and the next closing fence, line end included.
func proseBlock(prose, label string) (string, error) {
	start := strings.Index(prose, proseSectionStart)
	if start < 0 {
		return "", fmt.Errorf("no CLI-3 section")
	}
	section := prose[start:]
	if end := strings.Index(section, proseSectionEnd); end >= 0 {
		section = section[:end]
	}
	open := label + "\n```\n"
	switch n := strings.Count(section, open); {
	case n == 0:
		return "", fmt.Errorf("no fenced block after %s", label)
	case n > 1:
		return "", fmt.Errorf("%d fenced blocks after %s", n, label)
	}
	_, rest, _ := strings.Cut(section, open)
	block, _, ok := strings.Cut(rest, "```")
	if !ok {
		return "", fmt.Errorf("fenced block after %s is not closed", label)
	}
	return block, nil
}

// handlersConstant returns the decoded value of one template-literal constant of handlers.js.
func handlersConstant(js, constName string) (string, error) {
	open := "const " + constName + " = `"
	switch n := strings.Count(js, open); {
	case n == 0:
		return "", fmt.Errorf("no constant %s", constName)
	case n > 1:
		return "", fmt.Errorf("%d constants %s", n, constName)
	}
	_, rest, _ := strings.Cut(js, open)
	value, _, ok := strings.Cut(rest, "`")
	if !ok {
		return "", fmt.Errorf("constant %s is not closed", constName)
	}
	return strings.ReplaceAll(value, `\n`, "\n"), nil
}

// checkHelpPages compares every printed page with its block in the chapter and its constant in
// handlers.js and returns one error per mismatch or missing or repeated copy.
func checkHelpPages(printed map[string]string, prose, js string) []error {
	var errs []error
	for _, p := range helpPageDocs {
		block, err := proseBlock(prose, p.label)
		if err != nil {
			errs = append(errs, fmt.Errorf("help page %s in chapter 09: %v", p.name, err))
		} else if err := comparePage(p.name, "chapter 09", printed[p.name], block); err != nil {
			errs = append(errs, err)
		}
		value, err := handlersConstant(js, p.constName)
		if err != nil {
			errs = append(errs, fmt.Errorf("help page %s in handlers.js: %v", p.name, err))
		} else if err := comparePage(p.name, "handlers.js constant "+p.constName, printed[p.name], value); err != nil {
			errs = append(errs, err)
		}
	}
	return errs
}

func proseFixture(pages map[string]string, edit func(name, block string) string) string {
	var b strings.Builder
	b.WriteString(proseSectionStart + " Byte-exact.\n\n")
	for _, p := range helpPageDocs {
		fmt.Fprintf(&b, "%s\n```\n%s```\n\n", p.label, edit(p.name, pages[p.name]))
	}
	b.WriteString(proseSectionEnd + " — Streams.**\n")
	return b.String()
}

func handlersFixture(pages map[string]string, edit func(name, page string) string) string {
	var b strings.Builder
	for _, p := range helpPageDocs {
		fmt.Fprintf(&b, "const %s = `%s`;\n", p.constName, strings.ReplaceAll(edit(p.name, pages[p.name]), "\n", `\n`))
	}
	return b.String()
}

func keep(_, s string) string { return s }

func joinErrors(errs []error) string {
	var parts []string
	for _, e := range errs {
		parts = append(parts, e.Error())
	}
	return strings.Join(parts, "\n")
}

func TestPrintedHelpPagesMatchChapter09AndHandlers(t *testing.T) {
	prose, err := os.ReadFile("../spec/prose/09-cli-and-process.md")
	if err != nil {
		t.Fatal(err)
	}
	js, err := os.ReadFile("../test/acceptance/support/handlers.js")
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range checkHelpPages(printedHelpPages(t), string(prose), string(js)) {
		t.Error(e)
	}
}

func TestHelpPageDriftIsRejectedAndNamed(t *testing.T) {
	pages := printedHelpPages(t)
	const login = "  login                    On an interactive terminal, ask which account to use and guide the sign-in\n"
	if !strings.Contains(pages["provider"], login) {
		t.Fatal("printed provider page lacks the login line")
	}
	dropLogin := func(name, s string) string {
		if name == "provider" {
			return strings.Replace(s, login, "", 1)
		}
		return s
	}
	got := joinErrors(checkHelpPages(pages, proseFixture(pages, dropLogin), handlersFixture(pages, keep)))
	for _, want := range []string{"help page provider", "chapter 09", strings.TrimSuffix(login, "\n")} {
		if !strings.Contains(got, want) {
			t.Errorf("chapter 09 drift error lacks %q: %s", want, got)
		}
	}
	if strings.Contains(got, "handlers.js") {
		t.Errorf("clean handlers.js reported: %s", got)
	}
	got = joinErrors(checkHelpPages(pages, proseFixture(pages, keep), handlersFixture(pages, dropLogin)))
	if !strings.Contains(got, "providerHelp") || strings.Contains(got, "chapter 09") {
		t.Errorf("handlers.js drift error does not name providerHelp alone: %s", got)
	}
	if errs := checkHelpPages(pages, proseFixture(pages, keep), handlersFixture(pages, keep)); len(errs) != 0 {
		t.Errorf("identical fixtures rejected: %v", errs)
	}
}

func TestMissingOrRepeatedHelpBlockIsRejected(t *testing.T) {
	pages := printedHelpPages(t)
	clean := handlersFixture(pages, keep)
	prose := proseFixture(pages, keep)
	missing := strings.Replace(prose, helpPageDocs[1].label+"\n```\n"+pages["intent"]+"```\n\n", "", 1)
	if got := joinErrors(checkHelpPages(pages, missing, clean)); !strings.Contains(got, "help page intent") {
		t.Errorf("missing intent block not rejected by name: %q", got)
	}
	block := helpPageDocs[2].label + "\n```\n" + pages["provider"] + "```\n\n"
	twice := strings.Replace(prose, block, block+block, 1)
	if got := joinErrors(checkHelpPages(pages, twice, clean)); !strings.Contains(got, "help page provider") {
		t.Errorf("repeated provider block not rejected by name: %q", got)
	}
}

func TestFinalLineEndOfABlockIsCompared(t *testing.T) {
	pages := printedHelpPages(t)
	noFinalLF := proseFixture(pages, keep)
	noFinalLF = strings.Replace(noFinalLF, pages["provider"]+"```", strings.TrimSuffix(pages["provider"], "\n")+"```", 1)
	got := joinErrors(checkHelpPages(pages, noFinalLF, handlersFixture(pages, keep)))
	if !strings.Contains(got, "help page provider") {
		t.Errorf("a provider block without its final line end was not rejected: %q", got)
	}
}

